<span class="line"><span style="color:#C678DD;">public</span><span style="color:#C678DD;"> class</span><span style="color:#E5C07B;"> Cat</span><span style="color:#ABB2BF;"> : </span><span style="color:#E5C07B;">IAnimal</span></span>
